export function soundHandoffLabels(language='EN'){
 const i=Math.max(0,['EN','HU','DE','FR','ES','IT','PT','PL'].indexOf(language)),w={title:'Sounds received from Sound workshop|Hangok érkeztek a Hangműhelyből|Klänge aus Klangwerkstatt empfangen|Sons reçus de l’atelier sonore|Sonidos recibidos del taller|Audio ricevuti dal laboratorio|Sons recebidos da oficina|Dźwięki z pracowni dźwięku',apply:'Add audio tracks|Hangsávok hozzáadása|Audiospuren hinzufügen|Ajouter pistes audio|Añadir pistas de audio|Aggiungi tracce audio|Adicionar faixas áudio|Dodaj ścieżki audio',dismiss:'Keep for later|Később fogadom|Später übernehmen|Garder pour plus tard|Guardar para después|Conserva per dopo|Guardar para depois|Zachowaj na później',applied:'Audio tracks added. Existing video edits were kept; Undo is available. Render a short preview to hear the mix.|Hangsávok hozzáadva. A korábbi videószerkesztés megmaradt; visszavonható. A keverést rövid renderelt előnézettel hallgasd meg.|Spuren hinzugefügt. Videoschnitt bleibt, rückgängig möglich. Mix in Vorschau prüfen.|Pistes ajoutées. Montage conservé, annulable. Écoutez le mix dans l’aperçu rendu.|Pistas añadidas. Montaje conservado, reversible. Prueba mezcla en vista renderizada.|Tracce aggiunte. Montaggio conservato, annullabile. Ascolta mix in anteprima renderizzata.|Faixas adicionadas. Montagem mantida, pode desfazer. Ouça mistura na prévia.|Ścieżki dodane. Montaż zachowany, można cofnąć. Sprawdź miks w renderowanym podglądzie.',help:'Review names, start times and volume before adding. Narration beyond the video end is trimmed by the final export. Source sound remains unless you mute it.|Hozzáadás előtt nézd át a neveket, kezdést és hangerőt. A videó végén túlnyúló narrációt az export levágja. Az eredeti hang megmarad, amíg nem némítod.|Namen, Start und Lautstärke prüfen. Sprache über Videoende wird gekürzt. Quellton bleibt, bis stummgeschaltet.|Vérifiez noms, débuts et volumes. Narration coupée à fin vidéo. Son source conservé sauf sourdine.|Revisa nombres, inicio y volumen. Narración recortada al fin. Fuente sigue salvo silenciar.|Controlla nomi, inizio e volume. Narrazione tagliata a fine video. Sorgente resta salvo muto.|Reveja nomes, início e volume. Narração cortada no fim. Som fonte mantido salvo silenciar.|Sprawdź nazwy, początek i głośność. Narracja ucięta na końcu filmu. Źródłowy dźwięk pozostaje bez wyciszenia.'};
 return Object.fromEntries(Object.entries(w).map(([k,v])=>[k,v.split('|')[i]]));
}

export function attachSoundHandoff({host,language,handoffFactory,labels,videoCore,getProject,getLibrary,isBusy,commit,loadLibrary,say,fail}){
 const H=handoffFactory(),t=labels(language),D=document,receiptKey=H.key+'.accepted',box=D.createElement('section');box.className='vw-incoming';box.hidden=true;host.append(box);let pending=null,hidden='';
 function accepted(){try{const ids=JSON.parse(localStorage.getItem(receiptKey));return Array.isArray(ids)?ids.filter(x=>typeof x==='string').slice(-40):[];}catch{return [];}}
 function read(){try{const raw=localStorage.getItem(H.key);pending=raw?H.normalize(JSON.parse(raw)):null;if(pending&&accepted().includes(pending.id))pending=null;}catch{pending=null;}refresh();}
 function refresh(){box.replaceChildren();box.hidden=!pending||pending.id===hidden;if(box.hidden)return;const title=D.createElement('h2');title.textContent=t.title;box.append(title);if(pending.name){const name=D.createElement('strong');name.textContent=pending.name;box.append(name);}for(const item of pending.items){const row=D.createElement('p');row.className='vw-help';row.textContent=item.asset.name+' · '+item.settings.at+' s · '+item.settings.gain+' dB';box.append(row);}const help=D.createElement('p');help.className='vw-help';help.textContent=t.help;box.append(help);for(const [name,fn]of [['apply',apply],['dismiss',()=>{hidden=pending.id;refresh();}]]){const b=D.createElement('button');b.type='button';b.textContent=t[name];b.dataset.soundAction=name;b.disabled=isBusy();b.addEventListener('click',fn);box.append(b);}}
 async function apply(){if(isBusy()||!pending)return;const snapshot=pending;try{await loadLibrary();if(isBusy()||pending?.id!==snapshot.id)return;if(accepted().includes(snapshot.id)){read();return;}const next=H.apply(snapshot,getProject(),videoCore,getLibrary());commit(next);try{localStorage.setItem(receiptKey,JSON.stringify([...accepted().filter(id=>id!==snapshot.id),snapshot.id].slice(-40)));}catch{}pending=null;refresh();say(t.applied);}catch(e){fail(e);}}
 window.addEventListener('storage',e=>{if(e.key===H.key||e.key===receiptKey)read();});read();return {refresh,read,apply,getPending:()=>pending};
}
